import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { useAudio } from '../contexts/AudioContext';
import '../styles/pages/LandingPage.css';

const LandingPage: React.FC = () => {
  const { playLandingMusic } = useAudio();
  const audioInitializedRef = useRef(false);
  const [showMessage, setShowMessage] = useState(true);
  
  // Ocultar el mensaje después de 5 segundos
  useEffect(() => {
    const timer = setTimeout(() => {
      setShowMessage(false);
    }, 5000);
    
    return () => clearTimeout(timer);
  }, []);
  
  // Intentar reproducir la música inmediatamente y en cada interacción del usuario
  useEffect(() => {
    if (!audioInitializedRef.current) {
      // Intentar reproducir inmediatamente
      playLandingMusic().then(() => {
        audioInitializedRef.current = true;
      });
      
      // Crear un elemento de audio oculto
      const hiddenAudio = document.createElement('audio');
      hiddenAudio.src = '/assets/audio/landing-theme.mp3';
      hiddenAudio.loop = true;
      hiddenAudio.style.display = 'none';
      document.body.appendChild(hiddenAudio);
      
      // Intentar reproducirlo también
      hiddenAudio.play().catch(() => console.log('Reproducción alternativa fallida'));
      
      // Capturar cualquier interacción para iniciar la música
      const startAudioOnInteraction = () => {
        if (!audioInitializedRef.current) {
          playLandingMusic();
          audioInitializedRef.current = true;
        }
        
        // Limpiar eventos después del primer uso
        ['click', 'touchstart', 'keydown'].forEach(eventType => {
          document.removeEventListener(eventType, startAudioOnInteraction);
        });
      };
      
      // Agregar listeners para varios tipos de interacciones
      ['click', 'touchstart', 'keydown'].forEach(eventType => {
        document.addEventListener(eventType, startAudioOnInteraction);
      });
      
      return () => {
        // Limpiar
        ['click', 'touchstart', 'keydown'].forEach(eventType => {
          document.removeEventListener(eventType, startAudioOnInteraction);
        });
        document.body.removeChild(hiddenAudio);
      };
    }
  }, [playLandingMusic]);

  return (
    <div className="landing-page">
      {showMessage && (
        <div className="audio-message">
          Haz clic en cualquier parte para activar la música
        </div>
      )}
      
      <div className="landing-content">
        <div className="title-container">
          <h1 className="game-title">Heroes&Hostias</h1>
        </div>
        
        <div className="buttons-container">
          <Link to="/login" className="landing-button login-button">
            <span className="button-text">Iniciar Sesión</span>
          </Link>
          
          <Link to="/register" className="landing-button register-button">
            <span className="button-text">Registrarse</span>
          </Link>
        </div>
      </div>
      
      <div className="version-footer">
        <span>v1.0.0 Beta</span>
      </div>
      
      {/* Audio element oculto como alternativa */}
      <audio 
        src="/assets/audio/landing-theme.mp3"
        loop
        autoPlay
        style={{ display: 'none' }}
      />
    </div>
  );
};

export default LandingPage;
